source("helper.R")
key <- jwk_oct(K32); NOW <- as.POSIXct(1000, origin = "1970-01-01", tz = "UTC")
jd <- function(label, cj, ..., header = '{"alg":"HS256","typ":"JWT"}', now = NOW, show = NULL) {
  r <- try_(label, jwt_decode(hs(header, cj, K32), key, "HS256", now = now, ...))
  if (!is.null(show) && inherits(r, "jwt_claims")) print(unclass(r)[[show]])
  invisible(r)
}
cat("--- exp\n")
jd("exp 1060 (now=1000+leeway60: exp+leeway=1120)", '{"exp":1060}'); jd("exp 941", '{"exp":941}'); jd("exp 940 (==now-leeway) ", '{"exp":940}'); jd("exp 939", '{"exp":939}')
jd("exp 1000 leeway0", '{"exp":1000}', leeway = 0); jd("exp 1001 leeway0", '{"exp":1001}', leeway = 0); jd("exp 1000.5 leeway0", '{"exp":1000.5}', leeway = 0)
jd("exp string", '{"exp":"2000"}'); jd("exp null", '{"exp":null}'); jd("exp true", '{"exp":true}'); jd("exp array", '{"exp":[2000]}'); jd("exp 1e400", '{"exp":1e400}'); jd("exp 1e308", '{"exp":1e308}', show = "exp")
jd("exp -0", '{"exp":-0}'); jd("exp neg", '{"exp":-5}'); jd("exp 2e3", '{"exp":2e3}'); jd("exp big int", '{"exp":9223372036854775807}', show = "exp"); jd("exp 2^31", '{"exp":2147483648}', show = "exp")
jd("exp missing", '{"sub":"a"}'); jd("exp missing, required none", '{"sub":"a"}', required = character())
jd("exp object", '{"exp":{}}'); jd("exp 1e-400", '{"exp":1e-400}')
cat("--- nbf/iat\n")
jd("nbf 1060", '{"exp":2000,"nbf":1060}'); jd("nbf 1061", '{"exp":2000,"nbf":1061}'); jd("nbf string", '{"exp":2000,"nbf":"5"}'); jd("nbf null", '{"exp":2000,"nbf":null}')
jd("iat 1060", '{"exp":2000,"iat":1060}'); jd("iat 1061", '{"exp":2000,"iat":1061}'); jd("iat 1e308", '{"exp":2000,"iat":1e308}'); jd("iat neg", '{"exp":2000,"iat":-1e308}', max_age = 10)
jd("max_age: iat 900, max 40 (+60)", '{"exp":2000,"iat":900}', max_age = 40); jd("max_age: iat 899", '{"exp":2000,"iat":899}', max_age = 40); jd("max_age no iat", '{"exp":2000}', max_age = 40)
jd("max_age 0 leeway 0 iat=now", '{"exp":2000,"iat":1000}', max_age = 0, leeway = 0)
try_("max_age NA", jd("x", '{"exp":2000}', max_age = NA)); jd("max_age -1", '{"exp":2000,"iat":1000}', max_age = -1); jd("leeway NA", '{"exp":2000}', leeway = NA_real_); jd("leeway Inf", '{"exp":2000}', leeway = Inf); jd("leeway '60'", '{"exp":2000}', leeway = "60")
jd("leeway difftime mins", '{"exp":941}', leeway = as.difftime(1, units = "mins")); jd("max_age difftime 1 min (iat 800)", '{"exp":2000,"iat":800}', max_age = as.difftime(1, units = "mins"), leeway = 0)
jd("max_age difftime 1 hour (iat 800, age 200)", '{"exp":2000,"iat":800}', max_age = as.difftime(1, units = "hours"), leeway = 0)
jd("now numeric", '{"exp":2000}', now = 1000); jd("now NA", '{"exp":2000}', now = as.POSIXct(NA)); jd("now Date", '{"exp":2000}', now = Sys.Date()); jd("now POSIXlt", '{"exp":2000}', now = as.POSIXlt(NOW))
cat("--- aud/iss/sub\n")
jd("aud str ok", '{"exp":2000,"aud":"a"}', audience = "a"); jd("aud arr ok", '{"exp":2000,"aud":["b","a"]}', audience = "a"); jd("aud arr miss", '{"exp":2000,"aud":["b","c"]}', audience = "a")
jd("aud multi audience arg", '{"exp":2000,"aud":"b"}', audience = c("a", "b")); jd("aud present, no arg", '{"exp":2000,"aud":"a"}'); jd("aud absent, arg", '{"exp":2000}', audience = "a")
jd("aud []", '{"exp":2000,"aud":[]}', audience = "a"); jd("aud [] no arg", '{"exp":2000,"aud":[]}'); jd("aud null no arg", '{"exp":2000,"aud":null}'); jd("aud null arg", '{"exp":2000,"aud":null}', audience = "a")
jd("aud [1,'a']", '{"exp":2000,"aud":[1,"a"]}', audience = "a"); jd("aud number", '{"exp":2000,"aud":1}', audience = "1"); jd("aud nested", '{"exp":2000,"aud":[["a"]]}', audience = "a"); jd("aud object", '{"exp":2000,"aud":{"a":"a"}}', audience = "a")
jd("aud case", '{"exp":2000,"aud":"A"}', audience = "a"); jd("aud ''", '{"exp":2000,"aud":""}', audience = ""); jd("aud unicode nfc/nfd", '{"exp":2000,"aud":"e\\u0301"}', audience = "é")
jd("aud escaped equal", '{"exp":2000,"aud":"\\u0061"}', audience = "a"); jd("audience NA", '{"exp":2000,"aud":"a"}', audience = NA_character_); jd("audience empty chr", '{"exp":2000,"aud":"a"}', audience = character())
jd("iss ok", '{"exp":2000,"iss":"me"}', issuer = "me"); jd("iss bad", '{"exp":2000,"iss":"me2"}', issuer = "me"); jd("iss array", '{"exp":2000,"iss":["me"]}', issuer = "me"); jd("iss missing", '{"exp":2000}', issuer = "me")
jd("iss number no arg", '{"exp":2000,"iss":5}'); jd("iss null", '{"exp":2000,"iss":null}', issuer = "me"); jd("sub ok", '{"exp":2000,"sub":"s"}', subject = "s"); jd("sub number", '{"exp":2000,"sub":5}', subject = "5")
jd("iss latin1 arg", '{"exp":2000,"iss":"caf\\u00e9"}', issuer = iconv("café", "UTF-8", "latin1")); jd("iss utf8 arg", '{"exp":2000,"iss":"caf\\u00e9"}', issuer = "café")
jd("aud latin1 arg", '{"exp":2000,"aud":"caf\\u00e9"}', audience = iconv("café", "UTF-8", "latin1"))
cat("--- claims/required/validate\n")
jd("claims int eq", '{"exp":2000,"n":1}', claims = list(n = 1)); jd("claims 1L", '{"exp":2000,"n":1}', claims = list(n = 1L)); jd("claims 1.0 token", '{"exp":2000,"n":1.0}', claims = list(n = 1)); jd("claims 1e0 token", '{"exp":2000,"n":1e0}', claims = list(n = 1L))
jd("claims 1.5", '{"exp":2000,"n":1.5}', claims = list(n = 1.5)); jd("claims big", '{"exp":2000,"n":12345678901}', claims = list(n = 12345678901)); jd("claims 0.1+0.2", '{"exp":2000,"n":0.3}', claims = list(n = 0.1 + 0.2))
jd("claims str", '{"exp":2000,"s":"a"}', claims = list(s = "a")); jd("claims str vs arr", '{"exp":2000,"s":["a"]}', claims = list(s = "a")); jd("claims arr vs vec", '{"exp":2000,"s":["a","b"]}', claims = list(s = c("a", "b")))
jd("claims arr1 vs list", '{"exp":2000,"s":["a"]}', claims = list(s = list("a"))); jd("claims bool", '{"exp":2000,"b":true}', claims = list(b = TRUE)); jd("claims '1' vs 1", '{"exp":2000,"n":"1"}', claims = list(n = 1)); jd("claims true vs 'true'", '{"exp":2000,"b":"true"}', claims = list(b = TRUE))
jd("claims null vs NULL", '{"exp":2000,"z":null}', claims = list(z = NULL)); jd("claims NA", '{"exp":2000,"z":null}', claims = list(z = NA)); jd("claims obj", '{"exp":2000,"o":{"b":1,"a":2}}', claims = list(o = list(a = 2, b = 1)))
jd("claims fn", '{"exp":2000,"n":5}', claims = list(n = function(x) x > 3)); jd("claims fn non-TRUE", '{"exp":2000,"n":5}', claims = list(n = function(x) 1)); jd("claims fn missing claim", '{"exp":2000}', claims = list(n = function(x) TRUE))
jd("claims exp (posix?)", '{"exp":2000}', claims = list(exp = 2000)); jd("claims exp fn sees", '{"exp":2000}', claims = list(exp = function(x) { cat("   class:", class(x), "\n"); TRUE }))
jd("required jti null", '{"exp":2000,"jti":null}', required = c("exp", "jti")); jd("required jti missing", '{"exp":2000}', required = c("exp", "jti")); jd("required NA", '{"exp":2000}', required = NA_character_)
jd("validate TRUE", '{"exp":2000}', validate = function(cl) TRUE); jd("validate 'yes'", '{"exp":2000}', validate = function(cl) "yes"); jd("validate sees", '{"exp":2000}', validate = function(cl) { cat("   exp class:", class(cl$exp), "\n"); TRUE })
cat("--- payload shape\n")
jd("payload array", '[1]'); jd("payload dup", '{"exp":2000,"exp":1}'); jd("payload nested dup", '{"exp":2000,"a":{"x":1,"x":2}}'); jd("payload bom", '﻿{"exp":2000}'); jd("payload ws", ' {"exp":2000} '); jd("payload empty", ''); jd("payload trailing", '{"exp":2000}x')
jd("payload invalid utf8", as.raw(c(0x7b, 0x22, 0xff, 0x22, 0x3a, 0x31, 0x7d))); jd("payload NUL in string", '{"exp":2000,"s":"a\\u0000b"}'); jd("payload lone surrogate", '{"exp":2000,"s":"\\ud800"}')
jd("deep nesting", paste0('{"exp":2000,"d":', strrep("[", 5000), strrep("]", 5000), "}"))
cat("--- typ\n")
for (ty in c('"JWT"', '"jwt"', '"application/jwt"', '"APPLICATION/JWT"', '"at+jwt"', '"application/at+jwt"', '"JWS"', '""', '"application/"', '"jwt "', '"application/application/jwt"', '"application/jwt; charset=utf-8"')) jd(paste("typ", ty), '{"exp":2000}', header = sprintf('{"alg":"HS256","typ":%s}', ty))
jd("typ absent", '{"exp":2000}', header = '{"alg":"HS256"}'); jd("typ absent, type at+jwt", '{"exp":2000}', header = '{"alg":"HS256"}', type = "at+jwt"); jd("typ at+jwt type at+jwt", '{"exp":2000}', header = '{"alg":"HS256","typ":"application/at+jwt"}', type = "at+jwt")
jd("typ JWT, type NULL", '{"exp":2000}', header = '{"alg":"HS256","typ":"zzz"}', type = NULL); jd("typ null", '{"exp":2000}', header = '{"alg":"HS256","typ":null}'); jd("typ number", '{"exp":2000}', header = '{"alg":"HS256","typ":1}')
jd("type 'application/jwt' vs typ JWT", '{"exp":2000}', type = "application/jwt"); jd("type regex-ish", '{"exp":2000}', header = '{"alg":"HS256","typ":"aXjwt"}', type = "a.jwt")
cat("--- serialization\n")
tk <- hs('{"alg":"HS256"}', '{"exp":2000}', K32); p <- strsplit(tk, ".", fixed = TRUE)[[1]]
try_("json flattened", jwt_decode(sprintf('{"payload":"%s","protected":"%s","signature":"%s"}', p[2], p[1], p[3]), key, "HS256", now = NOW))
try_("ws+json", jwt_decode(sprintf(' \n{"payload":"%s","protected":"%s","signature":"%s"}', p[2], p[1], p[3]), key, "HS256", now = NOW))
try_("bom+json", jwt_decode(sprintf('﻿{"payload":"%s","protected":"%s","signature":"%s"}', p[2], p[1], p[3]), key, "HS256", now = NOW))
try_("jws_verify bom+json", jws_verify(sprintf('﻿{"payload":"%s","protected":"%s","signature":"%s"}', p[2], p[1], p[3]), key, "HS256"))
h <- b64('{"alg":"HS256","b64":false,"crit":["b64"]}'); pl <- '{"exp":2000}'
tb <- paste0(h, ".", pl, ".", b64(zucrypt::crypt_hmac(charToRaw(paste0(h, ".", pl)), K32, "sha256")))
try_("b64:false JWT (RFC 7797 s7 forbids)", jwt_decode(tb, key, "HS256", now = NOW))
try_("detached JWT", jwt_decode(sub("\\.[^.]*\\.", "..", tk), key, "HS256", now = NOW))
try_("limits token", jwt_decode(tk, key, "HS256", now = NOW, limits = jose_limits(token = 10)))
try_("decoder", jwt_decoder(key, "HS256")(tk, now = NOW)); try_("decoder no algorithms", jwt_decoder(key)); try_("decode alg none", jwt_decode(tk, key, "none", now = NOW))
r <- jwt_decode(tk, key, "HS256", now = NOW); str(unclass(r))
